package com.bibliotech.auth.security; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService {@Value("${jwt.secret}") String secret; @Value("${jwt.expiration-ms}") long expiry; private SecretKey key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String create(Long id,String email,String role){return Jwts.builder().subject(email).claim("userId",id).claim("role",role).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiry)).signWith(key()).compact();}}
